import{_ as a,o as e,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"TUI 浏览器","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/advanced/tui.md","filePath":"zh-CN/advanced/tui.md","lastUpdated":1784903584000}'),o={name:"zh-CN/advanced/tui.md"};function d(r,t,s,n,c,h){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="tui-浏览器" tabindex="-1">TUI 浏览器 <a class="header-anchor" href="#tui-浏览器" aria-label="Permalink to &quot;TUI 浏览器&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>swag2mcp 包含一个内置的 TUI（终端用户界面），用于交互式 API 探索。它是一个全屏终端应用程序，让你无需离开终端即可搜索、浏览、检查和调用 API 端点。</p><h2 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to &quot;启动&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>如果不存在配置文件，TUI 将自动首先启动初始化向导。</p><h2 id="模式" tabindex="-1">模式 <a class="header-anchor" href="#模式" aria-label="Permalink to &quot;模式&quot;">​</a></h2><p>TUI 有三种模式，可使用 <code>Tab</code> 键切换：</p><h3 id="搜索模式" tabindex="-1">搜索模式 <a class="header-anchor" href="#搜索模式" aria-label="Permalink to &quot;搜索模式&quot;">​</a></h3><p>跨所有 spec 中所有端点的全文搜索。支持与 <code>search</code> MCP 工具相同的查询语法。</p><ul><li>输入查询以搜索端点名称、路径和描述</li><li>按方法、标签或路径过滤结果</li><li>一键查看端点详情</li><li>分页浏览结果（每页 10 项）</li></ul><h3 id="浏览模式" tabindex="-1">浏览模式 <a class="header-anchor" href="#浏览模式" aria-label="Permalink to &quot;浏览模式&quot;">​</a></h3><p>通过 spec 层次结构进行树形导航：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpoint</span></span></code></pre></div><ul><li>向下导航树以查找特定端点</li><li>查看端点详情（参数、请求体、响应）</li><li>直接从 TUI 调用 API</li><li>将端点详情保存为 JSON 文件</li></ul><h3 id="认证模式" tabindex="-1">认证模式 <a class="header-anchor" href="#认证模式" aria-label="Permalink to &quot;认证模式&quot;">​</a></h3><p>查看任何 spec 的认证令牌和头。用于调试或生成 curl 命令。</p><h2 id="控制" tabindex="-1">控制 <a class="header-anchor" href="#控制" aria-label="Permalink to &quot;控制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>操作</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>向上/向下导航</td></tr><tr><td><code>Enter</code></td><td>选择或打开</td></tr><tr><td><code>Esc</code></td><td>返回上一级</td></tr><tr><td><code>Tab</code></td><td>在搜索、浏览和认证模式之间切换</td></tr><tr><td><code>/</code></td><td>聚焦搜索输入</td></tr><tr><td><code>N</code> / <code>P</code></td><td>下一页 / 上一页</td></tr><tr><td><code>B</code></td><td>返回上一屏幕</td></tr><tr><td><code>M</code></td><td>返回主菜单</td></tr><tr><td><code>S</code></td><td>将端点详情保存为 JSON 文件</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>退出</td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>TUI 在导航过程中经历以下状态：</p><ol><li><strong>加载中</strong> — 从工作区加载数据</li><li><strong>搜索</strong> — 带查询输入的搜索模式</li><li><strong>浏览</strong> — 带 spec 列表的浏览模式</li><li><strong>Spec 列表</strong> — 所有 spec 的列表</li><li><strong>Collection 列表</strong> — spec 内的 collection</li><li><strong>Tag 列表</strong> — collection 内的标签</li><li><strong>端点列表</strong> — 标签内的端点</li><li><strong>端点详情</strong> — 完整的端点信息</li><li><strong>调用结果</strong> — API 调用结果</li><li><strong>错误</strong> — 带消息的错误状态</li></ol><h2 id="端点详情视图" tabindex="-1">端点详情视图 <a class="header-anchor" href="#端点详情视图" aria-label="Permalink to &quot;端点详情视图&quot;">​</a></h2><p>当你选择一个端点时，TUI 显示：</p><ul><li>HTTP 方法和路径</li><li>基础 URL 和完整 URL</li><li>摘要和描述</li><li>所有参数（名称、位置、类型、必需）</li><li>请求体模式（如果适用）</li><li>响应码和模式</li><li>弃用状态</li></ul><h2 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to &quot;要求&quot;">​</a></h2><ul><li><strong>终端大小：</strong> 至少 80×24 字符</li><li><strong>终端模拟器：</strong> 适用于大多数现代终端（iTerm2、Terminal.app、GNOME Terminal、Windows Terminal 等）</li><li><strong>SSH：</strong> 可通过 SSH 连接工作</li></ul><h2 id="重要说明" tabindex="-1">重要说明 <a class="header-anchor" href="#重要说明" aria-label="Permalink to &quot;重要说明&quot;">​</a></h2><ul><li><strong>自动初始化</strong> — 如果不存在配置文件，TUI 自动启动初始化向导</li><li><strong>分页</strong> — 列表每页 10 项。使用 <code>N</code> 和 <code>P</code> 导航</li><li><strong>保存端点详情</strong> — 在端点详情视图中按 <code>S</code> 将完整详情保存为当前目录中的 JSON 文件</li><li><strong>认证模式</strong> — 显示用于调试的令牌和头。在生产环境中，可以使用 <code>--disable-llm-auth</code> 禁用 auth 工具</li></ul>',29)])])}const g=a(o,[["render",d]]);export{u as __pageData,g as default};
